/* Подписи, что лежат в index.html голым русским: id → ключ словаря. Зовётся из applyLang() при каждой смене языка.
   «Назад» (13 кнопок) метится при первом вызове, пока там ещё русский, — потом читается из метки. */
function applyStaticLabels(){
  if (typeof L==='undefined') return;
  const T=[['konstruktorBtn','modeForge'],['forgeTabPlayBtn','forgeTabFly'],['forgeTabCreateBtn','forgeTabMake'],['diagCinemaTestBtn','diagCinemaTest'],['ptLenLbl','forgeRecapLen']];
  for (const [id,k] of T){ const el=document.getElementById(id); if(el && L[k]) el.textContent=L[k]; }
  const A=[['ffPlayBtn','aria-label','ariaStart'],['firstFlightClose','aria-label','ffcClose'],['ffDelBtn','aria-label','ffcDel'],['ptListGrp','aria-label','ptListT'],
    ['ptUndoBtn','aria-label','ariaUndo'],['ptNoteText','placeholder','phNote'],['ptListClose','aria-label','ffcClose'],['ptRandomSkyBtn','aria-label','ariaShuffle'],
    ['forgeSaveFavBtn','aria-label','ariaFavSave'],['angarPvZoomShare','aria-label','ariaShareFile'],['flightGalleryBtn','aria-label','galDoorLbl'],['csInput','placeholder','csRowK']];
  for (const [id,at,k] of A){ const el=document.getElementById(id); if(el && L[k]) el.setAttribute(at,L[k]); }
  document.querySelectorAll('[aria-label="Назад"]').forEach(el=>el.setAttribute('data-l10n-back','1'));
  document.querySelectorAll('[data-l10n-back]').forEach(el=>el.setAttribute('aria-label',L.back));
  const lh=document.querySelector('#ptListCardHead b'); if(lh && L.ptListT) lh.textContent=L.ptListT;
  if (typeof applyCharter==='function') applyCharter(); // 02.10.2026: Хартия на языке игрока
  if (typeof feedbackPhotoRender==='function') feedbackPhotoRender();
}
/* Хартия на других языках (02.10.2026, владелец: «переводить Хартию на другие языки»). Перевод ИИ, носитель языка не читал; смысл и порядок блоков те же, что в русском тексте (index.html, .charterBody).
   charterBlocks — 7 блоков по порядку: .chSub и шесть .chAct (внутренняя разметка). applyCharter() подменяет их при смене языка; русский остаётся в разметке. */
Object.assign(I18N.ru,{ charterByeNight:'Можете идти спать.', charterByeDay:'Можете идти играть.' });
Object.assign(I18N.en,{
  charterByeNight:'You can go to sleep.', charterByeDay:'You can go play now.',
  charterBlocks:[
`<span class="chSubH">Official notice.</span> Reading is not mandatory. Understanding even less so.`,
`<p>If, in your world, chance is still sold for money, tell a grown-up. If you are the grown-up, may your sanity help you.</p><p><b class="chS">Games were invented for playing.</b> You pay for enjoyment, you get it.</p><p>Then somebody sat down and did the math: a satisfied person spends once, and one who is never let go spends every day.</p><p class="chHit">From that day on, “games” were made for the second kind.</p>`,
`<p>Take a card game where, at the end, you have to shout one three-letter word.</p><p>You hold it in your hands, play with friends, give it as a gift, sell it.</p><p>Then the deck was put on a screen. The cards are the same, yet a screen has room for ads.</p><p>Now there is a video between rounds and a “buy coins” window before them. <b class="chS">Rest turned into a shift: window, video, window.</b></p><p><b>If this wears you out like work, it is not your imagination.</b></p><p>It gets worse. A deck is bought once. A chance to draw a rare card is bought until you get lucky.</p><p>A card is now a picture on a screen. A copy costs almost nothing, and it can be sold endlessly.</p><p class="chHit">The perfect product: it does not exist.</p>`,
`<p><b>Does it work? It works.</b></p><p>The game is free, but everything interesting in it has a price. The first hero upgrade costs pennies, each next one costs more than the last, and the final one costs as much as a rocket. And you have already put in so much that quitting feels like a waste. <b class="chS">The closer to the top, the pricier the air.</b></p><p><b>Keep going like this and on Netflix you will have to pull every episode out of a loot box.</b></p><p><b class="chS">If you want to walk down that road, I’m sorry: I suggest turning around now.</b></p>`,
`<p><b class="chS">Honest names don’t sell well, so everything was renamed.</b></p><p>The tiredness they hand you for free, so they can sell you its cancellation, was called <b>energy</b>.</p><p>An offer that comes back on Friday was called <b>limited</b>.</p><p>Work that you even pay for was called a <b>battle pass</b>.</p><p>A wage for logging in every day was called a <b>daily reward</b>.</p><p>A video you are obliged to watch to the end was called a <b>bonus</b>.</p><p>Routine was called an <b>achievement</b>.</p><p>Chance was called an <b>opportunity</b>.</p><p class="chHit">Everything stayed the same. It just started to sound like a game.</p>`,
`<p><b class="chS">The industry compared two paths: making something new or milking the old. And summed it up.</b></p><p class="chPor">Progress Department report. Virtual reality: studios are closing. “Match-three”: 6,000,000,000 dollars from a single game. Department conclusion: progress is unprofitable. The Progress Department is closed.</p><p class="chPor">Attention: some games are designed so that you cannot stop. If you managed to stop, please report the error to them.</p>`,
`<p>Doctors were once paid for their patients’ health. <b class="chS">It is better for us, too, when you are healthy.</b></p><p>To be honest: we are leading you too. <b class="chS">Only toward the sky, not toward your wallet.</b> Don’t take our word for it: <a class="chLink" href="https://github.com/exxxit-game/cosmogram-app" target="_blank" rel="noopener">the game’s code is open</a>.</p><p>And we need money too. “We” is one person with no knowledge of programming languages and <a class="chLink" href="https://claude.ai" target="_blank" rel="noopener">Claude</a>. The game is free, but it has costs: a server, a domain, an assistant, and the person has to eat too. For that there is a “Thank you” button and skins. They give no advantages in the game: your gratitude lights a star in the sky, and a skin shows a real phenomenon from science or a pattern from world culture. Your place on the leaderboard does not change.</p><p><b class="chS">Permanently excluded:</b> ads, the sale of victory, chance, and time, subscriptions, hidden payments, bait notifications, and pressure through hurry and guilt.</p><p>A review can be ordered. A rating can be bought. Players’ love cannot.</p><p><b class="chS">Inside (Playdead), Portal (Valve), and The Room (Fireproof Games) became beloved because people chose them, not reviewers.</b> The authors did not know in advance whether it would work. Two things helped: the feedback of those who played, and the authors’ own care for their creation. One without the other does not work: feedback is useless if the author is indifferent to their own product. Whole communities grew around these games. They have lived for decades without a single hook. We intend to find out whether that still works.</p><p class="chFin">Thank you for reading. <span id="chBye">You can go play now.</span> <b class="chS">You have come closer to science.</b></p>`
  ]
});
