const SUPPORTED_LANGS = ['ru','en','es','pt','fr','id','tr','vi','uk','de','it','fa','ar']; // v1.108.1: добавляются сюда по мере перевода I18N — порядок не важен
const LANG = (()=>{
  const _tgw = window.Telegram && window.Telegram.WebApp; // свой, независимый взгляд на тот же мост — core.js грузится ПОСЛЕ этого файла (глобальный const tg переопределять нельзя), а языку нужно решение ДО core.js
  const raw = (_tgw && _tgw.initDataUnsafe && _tgw.initDataUnsafe.user && _tgw.initDataUnsafe.user.language_code || '').toLowerCase();
  const found = SUPPORTED_LANGS.find(l => raw.startsWith(l)) || ((raw==='in'||raw.startsWith('in-')||raw.startsWith('in_')) ? 'id' : null); // 'in' — прежний код индонезийского (Java/Android)
  return found || 'ru'; // не распознали — честный дефолт, тот же, что был всегда
})();
let L = I18N[LANG]; // let: настройка языка переключает словарь на лету
/* 26.09.2026: единая точка перевода имени/факта скина-явления, используется во всех
   местах показа (angarPvNameFill, angarPvZoomDraw, angarPvStoryDraw, angarBuildGrid) —
   один источник правды вместо повторения одной и той же логики в 6 местах. cat — категория
   витрины ('color'/'flash'/'trail'/...), логика перевода трогает ТОЛЬКО 'color' (скины);
   вспышки/следы намеренно не тронуты (владелец: подождать, часть будет удалена). */
function skinI18nName(item, cat){
  if(!item) return '';
  if(cat!=='color') return item.name||'';
  if(typeof item.name==='number') return L.skinNames[item.name]||'';
  return (L.skinNamesById && L.skinNamesById[item.id]) || item.name || '';
}
function skinI18nFact(item, cat){
  if(!item || !item.fact) return '';
  if(cat!=='color') return item.fact;
  return (L.skinFactsById && L.skinFactsById[item.id]) || item.fact;
}
